ve') }}</strong></article><article><span>03 / DELIVERY</span><strong>{{ l('配送笔记','Delivery notes') }}</strong></article><article><span>04 / CARE</span><strong>{{ l('材质维护','Material care') }}</strong></article></div><section class="cm-care-orders"><button v-for="order in orders" :key="order.id" :data-testid="`shopping-service-order-${order.id}`" @click="emit('open-order',order.id)"><span>{{ formatLogisticsDate(order.createdAt) }}</span><strong>{{ order.items.map(x=>x.title).join(' / ') }}</strong><b>OPEN DOSSIER →</b></button></section></section></main></template>
